update public.business_entity_definitions set definition='{"label":"Hành động khắc phục","feature":"quality","mode":"document","misaDomain":false,"requiresApproval":true,"fields":{"source_kind":{"label":"Loại nguồn","type":"enum","values":{"safety_incidents":"Sự cố an toàn","quality_nonconformances":"Điểm không phù hợp"},"required":true},"source_id":{"label":"Hồ sơ nguồn","type":"text","required":true,"max":36,"lookup":{"kindField":"source_kind","kinds":["safety_incidents","quality_nonconformances"],"statuses":["posted"]}},"action_type":{"label":"Loại hành động","type":"enum","values":{"corrective":"Khắc phục","preventive":"Phòng ngừa","containment":"Ngăn chặn"},"required":true},"owner_staff_id":{"label":"Người phụ trách","type":"ref","ref":"staff","requiresFeature":"people","required":true},"due_on":{"label":"Hạn hoàn thành","type":"date","required":true},"action_plan":{"label":"Kế hoạch hành động","type":"text","required":true,"max":2000},"completed_on":{"label":"Ngày hoàn thành","type":"date"},"effectiveness_result":{"label":"Kết quả xác nhận","type":"text","max":1500},"verified_by":{"label":"Người xác nhận","type":"ref","ref":"staff","requiresFeature":"people"}}}'::jsonb where kind='corrective_actions';
update public.business_entity_definitions set definition='{"label":"Đề nghị thanh toán","feature":"accounting","mode":"document","misaDomain":true,"requiresApproval":true,"fields":{"request_type":{"label":"Loại đề nghị","type":"enum","values":{"supplier":"Nhà cung cấp","employee":"Nhân viên","other":"Khác"},"required":true},"partner_id":{"label":"Nhà cung cấp","type":"ref","ref":"partners"},"staff_id":{"label":"Nhân viên","type":"ref","ref":"staff","requiresFeature":"people"},"beneficiary_name":{"label":"Người thụ hưởng","type":"text","max":180},"project_id":{"label":"Công trình","type":"ref","ref":"projects","requiresFeature":"projects"},"source_kind":{"label":"Nguồn","type":"text","max":80,"kindOptions":["vendor_invoices","purchase_orders","salary_runs","advances","project_acceptances","loans"]},"source_id":{"label":"Chứng từ nguồn","type":"text","max":36,"lookup":{"kindField":"source_kind","kinds":["vendor_invoices","purchase_orders","salary_runs","advances","project_acceptances","loans"],"statuses":["posted","released","completed"]}},"requested_on":{"label":"Ngày đề nghị","type":"date","required":true},"due_on":{"label":"Hạn thanh toán","type":"date"},"amount":{"label":"Số tiền","type":"number","min":0.01,"required":true},"requested_account_id":{"label":"Tài khoản chi","type":"ref","ref":"gl_accounts"},"purpose":{"label":"Nội dung","type":"text","required":true,"max":500},"document_date":{"label":"Ngày chứng từ","type":"date","required":true}}}'::jsonb where kind='payment_requests';
update public.business_entity_definitions set definition='{"label":"Đối chiếu nguồn chi phí","feature":"costing","mode":"document","fields":{"journal_line_id":{"label":"Dòng chi phí đã ghi sổ","type":"ref","ref":"journal_lines","required":true},"work_order_id":{"label":"Lệnh sản xuất","type":"ref","ref":"work_orders","requiresFeature":"production"},"project_id":{"label":"Công trình","type":"ref","ref":"projects","requiresFeature":"projects"},"category":{"label":"Khoản mục","type":"enum","values":{"material":"Nguyên vật liệu","labor":"Nhân công","machine":"Máy","overhead":"Chi phí chung","depreciation":"Khấu hao / phân bổ"},"default":"material"},"amount":{"label":"Chi phí phân bổ","type":"number","min":0.0001,"default":0},"source_kind":{"label":"Nguồn vận hành","type":"enum","values":{"journal":"Sổ cái","material_issues":"Cấp vật tư sản xuất","project_materials":"Xuất vật tư công trình","production_reports":"Báo cáo sản xuất","project_costs":"Chi phí công trình"},"default":"journal"},"source_record_id":{"label":"Chứng từ vận hành","type":"text","max":50,"lookup":{"kindField":"source_kind","kinds":["material_issues","project_materials","production_reports","project_costs"],"statuses":["posted"]}},"document_date":{"label":"Ngày đối chiếu","type":"date","required":true}},"misaDomain":true,"requiresApproval":true}'::jsonb where kind='cost_source_links';
